// Parity with tools/verify_gdd.py (GDD 0.2.5, 21): every fixture group must match exactly.
// fixtures.json is generated by `python3 tools/verify_gdd.py --export`; never retype its cases.
import { describe, expect, it } from 'vitest';
import fixturesJson from '../content/fixtures.json';
import { content } from '../content';
import {
  consequencesFor, cycleCostMs, evaluateLoad, expandLevel, fnv1a32, isJam, mulberry32U32,
  parSeconds, shuffleIds, starsFor, zoneOf,
  type LoadEval, type RuleId, type Severity,
} from '../engine';
import { FixturesFile } from './fixturesSchema';

const fx = FixturesFile.parse(fixturesJson);
const { itemsById: defs, config: cfg } = content;

/** [rule, severity] pairs sorted like Python's sorted() on lists of strings. */
function pairs(e: LoadEval): [RuleId, Severity][] {
  return e.violations
    .map((v): [RuleId, Severity] => [v.rule, v.severity])
    .sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0));
}

describe('traps', () => {
  it.each(fx.traps.map((c) => [c.name, c] as const))('%s', (_name, c) => {
    const e = evaluateLoad(defs, c.load, cfg);
    expect({
      weight: e.weight,
      dryBulk: e.dryBulk,
      wetBulkTenths: e.wetBulkTenths,
      zone: e.zone,
      jam: e.jam,
      costMs: e.cycleCostMs,
      violations: pairs(e),
      illegal: e.illegal,
    }).toEqual(c.expect);
  });
});

describe('illegal states', () => {
  it.each(fx.illegal.map((c) => [c.name, c] as const))('%s', (_name, c) => {
    expect(evaluateLoad(defs, c.load, cfg).illegal).toEqual(c.expect);
  });
});

describe('numeric rules', () => {
  it.each(fx.zones)('zoneOf($weight, $dryBulk) = $zone', ({ weight, dryBulk, zone }) => {
    expect(zoneOf(weight, dryBulk)).toBe(zone);
  });

  it.each(fx.jam)('isJam($weight, $wetBulkTenths) = $jam', ({ weight, wetBulkTenths, jam }) => {
    expect(isJam(weight, wetBulkTenths, cfg)).toBe(jam);
  });

  it.each(fx.cycleCosts)('cycleCostMs($weight, $dryBulk) = $costMs', ({ weight, dryBulk, costMs }) => {
    expect(cycleCostMs(weight, dryBulk, cfg)).toBe(costMs);
  });

  it.each(fx.stars)('starsFor($violations, jam=$jam, $totalMs ms, par $parSeconds, $loads/$minLoads loads) = $stars', (c) => {
    expect(starsFor(c.violations, c.jam, c.totalMs, c.parSeconds, c.loads, c.minLoads)).toBe(c.stars);
  });
});

describe('rng', () => {
  it.each(fx.rng.fnv1a32)('fnv1a32($input)', ({ input, hash }) => {
    expect(fnv1a32(input)).toBe(hash);
  });

  it.each(fx.rng.mulberry32)('mulberry32U32($seed) first draws', ({ seed, u32 }) => {
    const next = mulberry32U32(seed);
    expect(u32.map(() => next())).toEqual(u32);
  });

  it('lostThresholdU32 matches config', () => {
    expect(cfg.lostThresholdU32).toBe(fx.rng.lostThresholdU32);
  });
});

describe('par', () => {
  it.each(fx.par.map((p) => [p.levelId, p] as const))('%s', (_id, p) => {
    const level = content.levels.find((l) => l.id === p.levelId)!;
    const sumCostMs = level.par.solution
      .map((load) => evaluateLoad(defs, load, cfg).cycleCostMs)
      .reduce((a, b) => a + b, 0);
    const itemCount = expandLevel(level).length;
    expect({ itemCount, sumCostMs, parSeconds: parSeconds(sumCostMs, level.par.multiplierTenths, itemCount) })
      .toEqual({ itemCount: p.itemCount, sumCostMs: p.sumCostMs, parSeconds: p.parSeconds });
    expect(level.par.seconds).toBe(p.parSeconds);
  });
});

describe('hamper shuffle', () => {
  it.each(fx.hamperShuffle.map((h) => [h.levelId, h] as const))('%s', (_id, h) => {
    const level = content.levels.find((l) => l.id === h.levelId)!;
    expect(expandLevel(level)).toEqual(h.instanceIdsIn);
    expect(shuffleIds(h.instanceIdsIn, h.levelSeed)).toEqual(h.instanceIdsOut);
  });
});

describe('consequences', () => {
  it.each(fx.consequences.map((c) => [c.name, c] as const))('%s', (_name, c) => {
    expect(consequencesFor(defs, c.load, c.levelSeed, c.loadIndex, cfg)).toEqual(c.expect);
  });
});

describe('4-3 without bag reuse', () => {
  it('uses at most 2 bags in total and every load is perfect', () => {
    expect(fx.noReuseAlternative43.reduce((n, load) => n + load.bags.length, 0)).toBeLessThanOrEqual(2);
    for (const load of fx.noReuseAlternative43) {
      const e = evaluateLoad(defs, load, cfg);
      expect({ violations: e.violations, jam: e.jam, illegal: e.illegal }).toEqual({ violations: [], jam: false, illegal: [] });
    }
  });

  it('holds the same items as the 4-3 level', () => {
    const level = content.levels.find((l) => l.id === '4-3')!;
    const ids = fx.noReuseAlternative43.flatMap((load) => [...load.items, ...load.bags.flat()]).sort();
    expect(ids).toEqual(level.par.solution.flatMap((load) => [...load.items, ...load.bags.flat()]).sort());
  });
});
